STAGES = [
    ["anneal", {"iters": 250, "t0": 0.05}, 42],
    ["fringe", {"tries": 50, "k": 6}, 43],
    ["hill", {"iters": 150}, 44]
]


def gamma(A):
    A = sorted(A)
    n = len(A)
    if n < 2:
        return 0.0
    s = set()
    d = set()
    for a in A:
        for b in A:
            s.add(a + b)
            d.add(a - b)
    ns, nd = len(s), len(d)
    if nd <= n or ns <= n:
        return 0.0
    return math.log(ns / n) / math.log(nd / n)


def _neighbour(A, rng, moves):
    B = set(A)
    lo, hi = min(B), max(B)
    m = rng.choice(moves)
    if m == "add":
        B.add(rng.randint(lo - 3, hi + 3))
    elif m == "remove" and len(B) > 4:
